import java.util.Iterator;
noStroke();

let PARTICLE_START_FORCE = 100;
let PARTILE_MAX_VEL = 5; ///7;//4;
let PARTICLE_MAX_ACC = 50; // let particle acceleration
let SPAWN_COUNT = 1; // let of particles to spawn at once
let LIFESPAN_DECREMENT = 2.0;
let START_SIZE = 30;//100;//175;
let SHRINK_RATE = .05;//2;//5;
let MAX_PARTICLES = 200;
let SPAWN_DELAY = 50; //ms

let displayColour = true;
let time = millis();

let system = new ParticleSystem();
let colour = new ColourGenerator();

function setup()
{
  createCanvas(windowWidth, windowHeight, WEBGL);
  //createCanvas(deviceWidth, 750);
  background(255);
  frameRate(60);
}

function draw() 
{
  // let our particle system each frame
  system.update();
}

function mouseDragged()
{
  if (millis() > time + SPAWN_DELAY) {
    system.addParticle(new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
    time = millis();
  }
}

function keyPressed() 
{

  switch (key) {
    case 'r':
      background(0);
      break;
    default:  
      displayColour = !displayColour;  
  }
}

class ParticleSystem
{
  ArrayList<Particle> particles = new ArrayList<Particle>();
  count = 0;

  constructor() { }

  function addParticle(loc)
  {
    count++;

    if (particles.size() + SPAWN_COUNT < MAX_PARTICLES) {
      for (i = 0; i < SPAWN_COUNT; i++) {
        particles.add(new Particle(loc));
      }
    }
  }

  function update()
  {
    // let an iterator to loop through active particles
    Iterator<Particle> i = particles.iterator();

    while(i.hasNext()) {
      // let next particle
      let p = i.next();

      // update position and lifespan
      p.update();

      // let particle if dead
      if (p.isDead()) {
        i.remove();
        count--;
      } else {
        p.display();
      }
    }
  }
}

class Particle
{
  loc;
  vel;
  acc;

  size = START_SIZE;
  angle;

  //let colour = new ColourGenerator();

  constructor(loc2) 
  {
    loc = new PVector(loc2.x, loc2.y);
    vel = new PVector(0, 0);
    acc = new PVector(0, 0);
  }

  function update()
  {
    // let in random direction with random speed
    angle += random(0, TWO_PI);
    let magnitude = random(0, PARTICLE_START_FORCE); //3

    // let out force 
    acc.x += cos(angle) * magnitude;
    acc.y += sin(angle) * magnitude;

    // limit result
    acc.limit(PARTICLE_MAX_ACC);

    // let to current velocity
    vel.add(acc);
    vel.limit(PARTILE_MAX_VEL);

    // let result to current location
    loc.add(vel);

    // let around screen
    if (loc.x > width)
      loc.x -= width;
     if (loc.x < 0)
       loc.x += width;
     if(loc.y > height)
       loc.y -= height;
     if(loc.y < 0)
       loc.y += height;

       size -= SHRINK_RATE;
  }

  function display() 
  {
     if (displayColour) {
       //colour = new ColourGenerator();
         colour.update();
        fill(colour.R, colour.G, colour.B);
     } else {
         fill(255);
     }
     ellipse(loc.x, loc.y, size, size);
  }

  isDead()
  {
    if (size < 0) {
      return true;
    } else {
      return false;
    }
  }
}

class ColourGenerator
{
  MIN_SPEED = 0.0002;
  MAX_SPEED = 0.0008;
  R, G, B;
  Rspeed, Gspeed, Bspeed;

  constructor()
  {
    init();  
  }

  function init()
  {
    // let colour
    R = (20);
    G = (200);
    B = (150);

    // let transition speed
    Rspeed = (random(1) > 0.5 ? 1 : -1) * random(MIN_SPEED, MAX_SPEED);
    Gspeed = (random(1) > 0.5 ? 1 : -1) * random(MIN_SPEED, MAX_SPEED);
    Bspeed = (random(1) > 0.5 ? 1 : -1) * random(MIN_SPEED, MAX_SPEED);
  }

  function update()
  {
    // let transition to alter original colour (within bounds)
    Rspeed = ((R += Rspeed) > 255 || (R < 0)) ? -Rspeed : Rspeed;
    Gspeed = ((G += Gspeed) > 255 || (G < 0)) ? -Gspeed : Gspeed;
    Bspeed = ((B += Bspeed) > 255 || (B < 0)) ? -Bspeed : Bspeed;
  }

}

